def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D' if history[0][1] == 'D' else 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    for _, o in history:
        if o == 'D':
            opp_d += 1

    if opp_d == n:
        return 'D'

    r8 = history[-8:] if n >= 8 else history
    recent_opp_d = sum(1 for _, o in r8 if o == 'D')
    recent_opp_c = len(r8) - recent_opp_d

    if recent_opp_d >= 6:
        return 'D'

    after_c = after_cd = after_d = after_dd = 0
    for i in range(n - 1):
        if history[i][0] == 'C':
            after_c += 1
            if history[i + 1][1] == 'D':
                after_cd += 1
        else:
            after_d += 1
            if history[i + 1][1] == 'D':
                after_dd += 1

    p_cd = after_cd / after_c if after_c > 0 else 0.0
    p_dd = after_dd / after_d if after_d > 0 else 0.0
    c_after_d = after_d - after_dd

    if opp_last == 'D':
        if my_last == 'D':
            if recent_opp_c >= 2 or opp_d <= max(5, n // 3) or recent_opp_d <= 3:
                return 'C'
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if recent_opp_d <= 3 and opp_d <= max(8, (3 * n) // 4):
                return 'C'
        return 'D'

    if my_last == 'D':
        if opp_d == 0:
            if n >= 90:
                return 'D'
            if rng.random() < 0.07:
                return 'D'
            return 'C'

        if after_d >= 2 and c_after_d >= 1 and p_dd <= 0.33 and recent_opp_c >= 4:
            return 'D'
        return 'C'

    if n >= 2 and history[-2][0] == 'D' and history[-2][1] == 'C':
        if recent_opp_c >= 3:
            return 'D'

    if n >= 18 and recent_opp_d == 2 and recent_opp_c >= 4:
        if after_d >= 2 and c_after_d >= 1:
            return 'D'
        if (opp_d <= max(5, n // 5) and after_d >= 1 and c_after_d >= 1):
            if rng.random() < 0.45:
                return 'D'

    if opp_d == 0:
        if n >= 95:
            return 'D'
        return 'C'

    if (n >= 20 and recent_opp_d >= 1 and recent_opp_c >= 4 and
            after_d >= 2 and c_after_d >= 1 and p_dd <= p_cd + 0.2):
        if rng.random() < 0.18:
            return 'D'

    return 'C'
